CREATE TABLE IF NOT EXISTS `dpn_medical_dispatch_calls` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`caller_cid` varchar(64) NULL,`call_type` varchar(32) NOT NULL,`priority` int NOT NULL,`message` varchar(500) NOT NULL,`coords` longtext NULL,`status` varchar(32) NOT NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_dispatch_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
